let homeland=PalaisHome.normalize(localRead('homeland',null),Date.now()),homeTab='garden',homeWalking=false;
function homeAvatar(){const a=homeland.avatar,c=PalaisHome.clothes[a.outfit].color;return `<svg viewBox="0 0 100 140" role="img" aria-label="你的家园小人"><ellipse cx="50" cy="132" rx="30" ry="6" fill="#99745e25"/><path d="M37 111v19m26-19v19" stroke="${a.skin}" stroke-width="10" stroke-linecap="round"/><path d="M30 132h15m10 0h15" stroke="#86615b" stroke-width="7" stroke-linecap="round"/><path d="M25 42Q23 6 50 8Q80 6 77 43L${a.style==='long'?'83 94H18':'76 57H25'}Z" fill="${a.hair}"/><path d="M31 76L18 100m51-24 13 24" stroke="${a.skin}" stroke-width="9" stroke-linecap="round"/><path d="M35 73Q50 65 65 73L78 115Q50 128 22 115Z" fill="${c}"/><path d="M31 104q19 9 38 0M39 77l11 12 11-12" fill="none" stroke="#fff8e7" stroke-width="4"/><ellipse cx="50" cy="44" rx="24" ry="28" fill="${a.skin}"/><path d="M25 37Q25 6 51 12Q79 8 75 38Q63 32 57 24Q42 40 25 37" fill="${a.hair}"/><path d="M40 46v3m20-3v3" stroke="#533e42" stroke-width="3" stroke-linecap="round"/><path d="M45 58q5 5 10 0" fill="none" stroke="#b57480" stroke-width="2"/><ellipse cx="34" cy="55" rx="5" ry="3" fill="#ec9caa77"/><ellipse cx="66" cy="55" rx="5" ry="3" fill="#ec9caa77"/><path d="M70 17l10-6v16l-10-6-10 6V11Z" fill="${c}"/></svg>`}
function homeDo(action){try{const result=PalaisHome.apply(homeland,action);localSave('homeland',result.state);homeland=result.state;toast(result.message);renderHomeland()}catch(e){toast(e.message||'保存失败，请检查浏览器空间')}}
function homeWalk(x,y,action){if(homeWalking)return;const el=$('#homeActor');if(!el){action?.();return}homeWalking=true;el.classList.add('walking');el.style.left=x+'%';el.style.top=y+'%';setTimeout(()=>{homeWalking=false;if(tab!=='homeland')return;homeland.position={x,y};el.classList.remove('walking');action?.()},650)}
function homeScene(){const pet=homeland.pet,icons={cat:'🐈',bunny:'🐇',dog:'🐕'};return `<div class="home-scene" id="homeScene" aria-label="家园花园，点击空地移动小人"><div class="garden-sky">✧ <span>JARDIN DES ROSES</span> ✧</div><div class="garden-house"><div>♔</div><i></i><i></i><b></b></div><div class="garden-fence"></div><span class="garden-tree">🌸</span><span class="garden-tree right">🌳</span><div class="garden-path"></div><button class="garden-pet" id="scenePet" aria-label="走近宠物">${pet?icons[pet.kind]:'🧺'}<small>${pet?escapeHtml(pet.name):'领养小伙伴'}</small></button><div class="garden-plots">${homeland.plots.map((p,i)=>`<button data-plot="${i}" aria-label="菜地 ${i+1}"><span>${p?(PalaisHome.ready(p,Date.now())?PalaisHome.crops[p.crop].fruit:p.watered?'🌿':'🌱'):'＋'}</span><small>${p?(PalaisHome.ready(p,Date.now())?'收获':p.watered?'生长中':'待浇水'):'空地'}</small></button>`).join('')}</div><div class="home-actor" id="homeActor" style="left:${homeland.position.x}%;top:${homeland.position.y}%">${homeAvatar()}</div><div class="scene-caption">点击空地散步 · 点击菜地或宠物互动</div></div>`}
function renderHomeland(){
 if(tab!=='homeland')return;homeland=PalaisHome.normalize(homeland,Date.now());
 screen.innerHTML=`<section class="view homeland"><div class="home-heading"><div><div class="eyebrow">YOUR LITTLE GARDEN</div><h2>玫瑰家园</h2></div><div class="points">✧ ${homeland.points}<small>家园积分</small></div></div>${homeScene()}<div class="home-tabs">${[['garden','花园'],['pet','宠物'],['dress','衣帽间'],['tasks','任务']].map(([id,n])=>`<button data-home-tab="${id}" class="${homeTab===id?'selected':''}">${n}</button>`).join('')}</div><div id="homeContent"></div><p class="section-note">家园进度保存在当前浏览器 · 积分仅用于家园<br>角色菜园为本地虚拟玩法</p></section>`;
 document.querySelectorAll('[data-home-tab]').forEach(b=>b.onclick=()=>{homeTab=b.dataset.homeTab;renderHomeland()});
 $('#homeScene').onclick=e=>{if(e.target.closest('button'))return;const r=e.currentTarget.getBoundingClientRect();homeWalk(Math.max(10,Math.min(85,(e.clientX-r.left)/r.width*100)),Math.max(43,Math.min(78,(e.clientY-r.top)/r.height*100)))};
 $('#scenePet').onclick=()=>homeWalk(22,58,()=>{homeTab='pet';renderHomeland()});
 document.querySelectorAll('[data-plot]').forEach(b=>b.onclick=()=>homeWalk(55,65,()=>homePlot(Number(b.dataset.plot))));
 const c=$('#homeContent');if(homeTab==='garden'){
 c.innerHTML=`<div class="home-card"><h3>我的小菜园 <span>四块田，一点慢时光</span></h3>${homeland.plots.map((p,i)=>`<button class="plot-row" data-garden-plot="${i}"><b>${p?PalaisHome.crops[p.crop].fruit:'🪴'}</b><div>${i+1} 号地 · ${p?PalaisHome.crops[p.crop].name:'等待播种'}<small>${p?(PalaisHome.ready(p,Date.now())?'成熟啦，点击收获':!p.watered?'点击浇水':`还需 ${Math.ceil(Math.max(0,PalaisHome.crops[p.crop].time-Date.now()+p.planted)/1000)} 秒`):'种下一份小小的期待'}</small></div><span>›</span></button>`).join('')}</div><div class="home-card"><h3>去朋友家摘菜 <span>每天最多三位，每位一次</span></h3>${roles.length?roles.map(r=>`<button class="plot-row" data-neighbor="${escapeHtml(r.id)}"><b>${escapeHtml(r.emoji)}</b><div>${escapeHtml(r.name)}的虚拟菜园<small>${homeland.daily.stolen.includes(r.id)?'今天已经摘过啦':'成熟的蔬菜 · 采摘 +8 积分'}</small></div><span>🥬</span></button>`).join(''):'先在微信中创建角色，再来拜访吧。'}</div>`;
 document.querySelectorAll('[data-garden-plot]').forEach(b=>b.onclick=()=>homeWalk(55,65,()=>homePlot(Number(b.dataset.gardenPlot))));document.querySelectorAll('[data-neighbor]').forEach(b=>b.onclick=()=>homeDo({type:'steal',id:b.dataset.neighbor}));
 }else if(homeTab==='pet')renderHomePet(c);else if(homeTab==='dress')renderHomeDress(c);else renderHomeTasks(c);
}
function homePlot(i){const p=homeland.plots[i];if(p){homeDo({type:PalaisHome.ready(p,Date.now())?'harvest':'water',index:i});return}const d=panel(`<h2>给 ${i+1} 号地选种子</h2>${Object.entries(PalaisHome.crops).map(([id,c])=>`<button class="plot-row" data-seed="${id}"><b>${c.fruit}</b><div>${c.name}<small>${c.time/60000} 分钟成熟 · ${c.cost} 积分播种 · 收获 +${c.reward}</small></div></button>`).join('')}<button class="secondary full" id="closeSeeds">再想想</button>`);$('#closeSeeds').onclick=()=>d.close();document.querySelectorAll('[data-seed]').forEach(b=>b.onclick=()=>{d.close();homeDo({type:'plant',index:i,crop:b.dataset.seed})})}
function renderHomePet(c){const p=homeland.pet;if(!p){c.innerHTML=`<form id="adoptPet" class="home-card"><h3>把小伙伴接回家</h3><label>选择宠物<select name="kind"><option value="cat">🐈 奶糖猫</option><option value="bunny">🐇 云朵兔</option><option value="dog">🐕 布丁犬</option></select></label><label>给 TA 起名字<input name="petName" maxlength="12" value="奶糖" required></label><button class="primary full">免费领养</button></form>`;$('#adoptPet').onsubmit=e=>{e.preventDefault();homeDo({type:'adopt',kind:e.target.kind.value,name:e.target.petName.value})};return}
 const n=PalaisHome.needs(p,Date.now());c.innerHTML=`<div class="home-card"><h3>${escapeHtml(p.name)} <span>${p.xp>=100?'长大啦':'幼年'} · 成长 ${p.xp} / 100</span></h3>${[['food','饱腹'],['clean','清洁'],['joy','心情']].map(([k,label])=>`<div class="pet-meter">${label}<progress max="100" value="${n[k]}"></progress><small>${n[k]}</small></div>`).join('')}<div class="care-actions">${[['food','🍰 喂食'],['clean','🛁 洗澡'],['joy','🧶 玩耍']].map(([k,l])=>`<button class="secondary" data-care="${k}">${l}</button>`).join('')}</div><p class="section-note">同种照料间隔一分钟，状态会随时间慢慢变化。<br>每次照料获得 10 成长值。</p><label>共同养育伙伴<select id="homePartner"><option value="">自己照料</option>${roles.map(r=>`<option value="${escapeHtml(r.id)}" ${homeland.partner===r.id?'selected':''}>${escapeHtml(r.name)}</option>`).join('')}</select></label><button class="primary full" id="partnerCare" ${roles.some(r=>r.id===homeland.partner)?'':'disabled'}>请伙伴一起照料</button><p class="section-note">伙伴照料使用本地互动，不调用 API。</p></div><div class="home-card"><h3>家园日记</h3>${homeland.log.slice(0,6).map(l=>`<p class="home-log">${escapeHtml(l.text)}</p>`).join('')}</div>`;
 document.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>homeWalk(22,58,()=>homeDo({type:'care',kind:b.dataset.care})));$('#homePartner').onchange=e=>homeDo({type:'partner',id:e.target.value});$('#partnerCare').onclick=()=>{const r=roles.find(r=>r.id===homeland.partner);if(!r)return;const k=Object.keys(n).sort((a,b)=>n[a]-n[b])[0];homeWalk(22,58,()=>homeDo({type:'care',kind:k,actor:r.name}))};
}
function renderHomeDress(c){const a=homeland.avatar;c.innerHTML=`<div class="home-card dress-card"><div class="dress-preview">${homeAvatar()}</div><form id="avatarForm"><h3>捏一个小小的你</h3><label>肤色<select name="skin">${[['#ffe2cc','蜜桃奶油'],['#e7b99b','温暖杏仁'],['#bd896e','焦糖可可']].map(([v,n])=>`<option value="${v}" ${a.skin===v?'selected':''}>${n}</option>`).join('')}</select></label><label>发色<select name="hair">${[['#765345','栗子棕'],['#302d39','夜幕黑'],['#c9a16c','蜂蜜金']].map(([v,n])=>`<option value="${v}" ${a.hair===v?'selected':''}>${n}</option>`).join('')}</select></label><label>发型<select name="style"><option value="long" ${a.style==='long'?'selected':''}>长发</option><option value="short" ${a.style==='short'?'selected':''}>短发</option></select></label><button class="primary full">保存造型</button></form></div><div class="home-card"><h3>宫廷衣橱 <span>积分购买后永久拥有</span></h3><div class="clothes-grid">${Object.entries(PalaisHome.clothes).map(([id,v])=>`<button class="outfit ${a.outfit===id?'selected':''}" data-outfit="${id}"><span style="color:${v.color}">♛</span><b>${v.name}</b><small>${a.outfit===id?'正在穿着':homeland.owned.includes(id)?'已拥有 · 换上':v.price+' 积分 · 购买并穿上'}</small></button>`).join('')}</div></div>`;
 $('#avatarForm').onsubmit=e=>{e.preventDefault();homeDo({type:'avatar',skin:e.target.skin.value,hair:e.target.hair.value,style:e.target.elements.namedItem('style').value})};document.querySelectorAll('[data-outfit]').forEach(b=>b.onclick=()=>homeDo({type:'wear',id:b.dataset.outfit}));}
function renderHomeTasks(c){const d=homeland.daily;c.innerHTML=`<div class="home-card"><h3>今日的小幸福 <span>每天重新开始</span></h3>${[['visit','来家园看看',true,10],['care','照料宠物两次',d.care>=2,20],['water','给两块菜地浇水',d.water>=2,15],['harvest','收获一块菜地',d.harvest>=1,20]].map(([id,n,done,reward])=>`<div class="task-row"><div>${n}<small>奖励 ${reward} 积分</small></div><button class="secondary" data-task="${id}" ${!done||d.claimed.includes(id)?'disabled':''}>${d.claimed.includes(id)?'已领取':done?'领取':'进行中'}</button></div>`).join('')}</div>`;document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>homeDo({type:'claim',id:b.dataset.task}));}
setInterval(()=>{if(tab==='homeland'&&!homeWalking&&!document.querySelector('dialog[open]')&&homeTab==='garden')renderHomeland()},10000);
